import { Drawer, Button } from "march/ui"

// Drawer'ın özellikleri: open, onClose, side, size, modal, dragToClose, snapPoints, snap, onSnap, handle, handleLabel,
// closeButton, motion, title, target
export function DrawerLab() {
  let $open = false
  let $snap = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <Button on:click={() => $open = true}>Çekmeceyi aç</Button>
    <span class="lab-snap">Durma noktası {$snap}</span>
    <Drawer open={$open} onClose={() => $open = false} side="top" size="md" modal={false} dragToClose={false}
      snapPoints={[0.3, 0.6]} onSnap={(i: number) => $snap = i} handle handleLabel="Çekmeceyi sürükle" closeButton
      motion={{ duration: 200 }} title="Duyurular">
      <p>Bugün iki yeni özellik yayında.</p>
    </Drawer>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DrawerLab } from "./DrawerLab.tsx"

// DrawerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("açılınca başlık ve içerik görünür", async () => {
  const s = renderTest(() => <DrawerLab />)
  await s.click("Çekmeceyi aç")
  await s.flush(2)
  expect(s.sees("Duyurular")).toBe(true)
  expect(s.sees("Bugün iki yeni özellik yayında.")).toBe(true)
})

test("tutamaç handleLabel adını alır", async () => {
  const s = renderTest(() => <DrawerLab />)
  await s.click("Çekmeceyi aç")
  await s.flush(2)
  expect(s.find("Çekmeceyi sürükle")).not.toBe(null)
})
